Rule.Source:
// MNB HR Identity Mapping for department
// Maps HR departmentName to identity warehouse department attribute

String departmentName = (String)link.getAttribute("departmentName");

if (departmentName != null && !departmentName.isEmpty()) {
    return departmentName.trim();
}

// Fallback to division attribute if departmentName is empty
String division = (String)link.getAttribute("division");
if (division != null && !division.isEmpty()) {
    return division.trim();
}

return null;
